        {
          "@type": "Question",
          "name": "Is wage inequality getting worse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Measured as the gap in payroll wages between occupations, it narrowed in 47 of 51 states since 2016. Since 2022 it is mixed: 11 states widened and 15 narrowed. Wage data leaves out investment income, so this does not show whether overall inequality fell."
          }
        },
        {
          "@type": "Question",
          "name": "Where does the income of the richest come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "On 2023 tax returns of $10 million or more, wages were 17% of income and capital gains 39%."
